/**================================================================================================================ **/
/** 기업지배구조 공시 뷰어의 html 깨짐 이슈로 기업지배구조 공시 뷰어 새창 보기 기능 추가(2023.12.14 bslee 추가) **/
/** include(jquery-1.11.0.min.js, json2.js) 추가 **/
/** 추가한 함수는 fn_viewerUrl()이고 event 함수로는 <event for="viewer_btn" eventname="onclick" > , 디자인 소스에서 '공시뷰어 새창열기' 버튼 추가함 **/
/** onload 이벤트 함수에는 기존에 아무런 로직이 없었고, 공시뷰어 새창보기 관련 로직이 새로 추가됨.  그 외에 다른 소스는 건드리지 않음. **/
scwin.dsclViewerUrl = "";
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
}; // 공시뷰어URL
scwin.fn_viewerUrl = function(gDisclsDocNo) {
    // 이전 화면에서 넘어 온 공시문서번호로 공시viewer url을 조회한다.
    // json 방식으로 호출
    $.ajax({
        type: "POST",
        url: "/EsgSearch.do",
        data: {
            method: "dsclViewerUrlSelectJson",
            disclsDocNo: gDisclsDocNo
        },
        dataType: 'JSON',
        success: function(data) {
            if (data.result == 'OK') {
                var listData = JSON.stringify(data);
                var obj = JSON.parse(listData);
                scwin.dsclViewerUrl = obj.contents.viewer_url;
                // 공시뷰어URL이 있을 경우만 버튼을 노출 시킴
                if (scwin.dsclViewerUrl != null && scwin.dsclViewerUrl != "undefined") {
                    viewer_btn.style.display = "block";
                }
            }
        },
        error: function(request, status, error) {
            $c.win.alert("공시뷰어 URL 조회 도중 오류가 발생 하였습니다.");
            return;
        }
    });
};



/**================================================================================================================ **/

scwin.gAtsSCCB = "";
scwin.strDepCd = "";
scwin.fn_sccbBtn = function(strDepCd, gAtsSCCB) {
    scwin.strDepCd = scwin.strDepCd.substring(0, 2);
    if (scwin.strDepCd == '22' || scwin.strDepCd == '32' || scwin.strDepCd == 'ZS') {
        if (scwin.gAtsSCCB != null && scwin.gAtsSCCB != "") {
            $c.stf.showObj(pnl_ats, true);
            btn_sccbBtn.style.display = "block";
            txaSCCB.text = "ATS의 " + scwin.gAtsSCCB + " 내역 수신 여부 확인을 위해 [ATS송수신 내역 조회]버튼을 클릭하십시오☞";
        } else {
            $c.stf.showObj(pnl_ats, false);
            btn_sccbBtn.style.display = "none";
        }
    } else {
        $c.stf.showObj(pnl_ats, false);
        btn_sccbBtn.style.display = "none";
    }
};
scwin.img_close_onclick = function() {
    $c.frame.path("../").fn_CloseWin();
};
scwin.img_print_onclick = function() {
    //fn_PrintFormCall();
    $c.frame.path("../frame_head").fn_PrintOpen();
};
scwin.gform_onload = function() {
    /**================================================================================================== **/
    /** 기업지배구조 공시 VIEWER 새창 보기 기능 추가(2023.12.14 bslee 추가) **/
    // 다른 공시에서는 버튼이 안보이게 default는 none 처리
    viewer_btn.style.display = "none"; // 공시뷰어 새창열기 버튼
    var gMainFormCd = $c.frame.path("../frame_head").gMainFormCd; // 이전 화면에서 넘어온 서식코드(기업지배구조 보고서 공시의 본문 서식번호는 99667, 기타공개첨부문서는 99926, 기타비공개첨부문서는 99927 )
    var gDisclsDocNo = $c.frame.path("../frame_head").gOpenDocNo; // 이전 화면에서 넘어온 공시문서번호
    // 기업지배구조 공시일 경우만 공시뷰어 URL을 조회
    // 테스트 결과 첨부문서가 추가되거나 첨부문서를 정정하여 생성 된 공시([추가],[첨부정정])를 클릭해도 서식코드는 무조건 99667로 올라왔음. 즉 if문의 조건에 99667만 있어도 될거 같으나 혹시 몰라 99926,99927도 조건에 넣어 URL 조회를 하게 함
    if (gMainFormCd == '99667' || gMainFormCd == '99926' || gMainFormCd == '99927') {
        // 공시뷰어URL 조회
        scwin.fn_viewerUrl(gDisclsDocNo);
    }
    /**================================================================================================== **/

    /** SCCB 공시에 대해 이동버튼 생성(20250228) **/
    // 다른 공시에서는 버튼이 안보이게 default는 none 처리
    btn_sccbBtn.style.display = "none";
    scwin.gAtsSCCB = $c.frame.path("../frame_head").scwin.gAtsSCCB;
    scwin.strDepCd = $c.frame.path("../frame_head").gDepCd;
    if (scwin.strDepCd != null && scwin.strDepCd != "undefined") {
        scwin.fn_sccbBtn(scwin.strDepCd, scwin.gAtsSCCB);
    }
};
scwin.viewer_btn_onclick = function() {
    // 공시뷰어 새창열기 버튼 클릭 시 URL로 이동(2023.12.14 bslee 추가)
    window.open('microsoft-edge:' + scwin.dsclViewerUrl, '_self'); // 익스플로러로 새창이 열리는 이슈가 있을 수 있어서 엣지로 강제 이동

};
scwin.btn_sccbBtn_onclick = async function() {
    // ATS 송수신 내역조회로 이동 
    await $c.frame.CreateDialogFrame("gform", "/dscltrend/ULDSTF35004.gfm", "CB/SC 관련 송수신 내역", 300, -600, 1300, 800, "window");
};
